using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
namespace NightLens {
class AltitudeChart:Control {
 public readonly List<AltitudePoint> Samples=new List<AltitudePoint>();Pick pick;Night night;ToolTip tip=new ToolTip();public Rectangle PlotBounds{get;private set;}public Rectangle BestReadoutBounds{get;private set;}public double MinAltitude{get;private set;}public double MaxAltitude{get;private set;}=95;
 public AltitudeChart(Pick p,Night n){pick=p;night=n;DoubleBuffered=true;Font=new Font("Segoe UI",9);Cursor=Cursors.Default;for(DateTime time=n.Start;time<=n.End;time=time.AddMinutes(10))Samples.Add(new AltitudePoint{Utc=time,Alt=n.Altitude(p.Target,time)});Samples.Add(new AltitudePoint{Utc=p.Best,Alt=n.Altitude(p.Target,p.Best)});Samples=Samples.OrderBy(x=>x.Utc).ToList();MinAltitude=Math.Min(0,Math.Floor(Samples.Min(x=>x.Alt)/15)*15-5);Disposed+=(a,b)=>tip.Dispose();MouseMove+=(a,b)=>{if(PlotBounds.Width<=0||!PlotBounds.Contains(b.Location))return;double position=Math.Max(0,Math.Min(1,(b.X-PlotBounds.Left)/(double)PlotBounds.Width));var time=night.Start.AddTicks((long)((night.End-night.Start).Ticks*position));var closest=Samples.OrderBy(x=>Math.Abs((x.Utc-time).TotalMinutes)).First();tip.SetToolTip(this,night.Time(closest.Utc)+" · "+closest.Alt.ToString("0.0")+"° altitude");};}
 public PointF Project(AltitudePoint point){return new PointF(PlotBounds.Left+(float)((point.Utc-night.Start).TotalHours/(night.End-night.Start).TotalHours)*PlotBounds.Width,PlotBounds.Bottom-(float)((point.Alt-MinAltitude)/(MaxAltitude-MinAltitude))*PlotBounds.Height);}
 void DrawText(Graphics g,string text,Rectangle rect,Color color,TextFormatFlags flags=TextFormatFlags.Left|TextFormatFlags.VerticalCenter){TextRenderer.DrawText(g,text,Font,rect,color,flags|TextFormatFlags.NoPrefix|TextFormatFlags.NoPadding);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Style.Card);int line=(int)Math.Ceiling(Font.GetHeight())+5;string readout="Best "+pick.Alt.ToString("0.0")+"° · "+night.Time(pick.Best);int readoutWidth=TextRenderer.MeasureText(readout,Font).Width+8,titleWidth=TextRenderer.MeasureText("ALTITUDE TRAJECTORY",Font).Width+8;bool single=titleWidth+readoutWidth+16<Width;DrawText(g,"ALTITUDE TRAJECTORY",new Rectangle(2,0,single?titleWidth:Width-4,line),Style.Text);BestReadoutBounds=single?new Rectangle(Width-readoutWidth-2,0,readoutWidth,line):new Rectangle(2,line,Width-4,line);DrawText(g,readout,BestReadoutBounds,Style.Text);int top=line*(single?1:2)+9,bottom=line*2+12;PlotBounds=new Rectangle(40,top,Math.Max(8,Width-62),Math.Max(8,Height-top-bottom));if(Height<top+bottom+20)return;using(var brush=new SolidBrush(Style.Bg))g.FillRectangle(brush,PlotBounds);Func<DateTime,float> x=t=>Project(new AltitudePoint{Utc=t,Alt=0}).X;Func<double,float> y=alt=>Project(new AltitudePoint{Utc=night.Start,Alt=alt}).Y;if(night.Dark.Count>0)using(var brush=new SolidBrush(Color.FromArgb(25,Style.Text)))g.FillRectangle(brush,x(night.Dark.First()),PlotBounds.Top,x(night.Dark.Last())-x(night.Dark.First()),PlotBounds.Height);
 using(var pen=new Pen(Color.FromArgb(65,Style.Muted))){var levels=new List<int>();foreach(int candidate in new[]{0,90,30,60,-30,-60,-90})if(candidate>=MinAltitude&&candidate<=MaxAltitude&&levels.All(value=>Math.Abs(y(value)-y(candidate))>=line+2))levels.Add(candidate);foreach(var alt in levels){if(alt!=30)g.DrawLine(pen,PlotBounds.Left,y(alt),PlotBounds.Right,y(alt));DrawText(g,alt+"°",new Rectangle(0,(int)y(alt)-line/2,34,line),Style.Muted,TextFormatFlags.Right|TextFormatFlags.VerticalCenter);}for(int hour=0;hour<=(night.End-night.Start).TotalHours;hour+=Width<360?6:4){var time=night.Start.AddHours(hour);g.DrawLine(pen,x(time),PlotBounds.Top,x(time),PlotBounds.Bottom);string label=night.S.Local(time).ToString("h tt");int width=TextRenderer.MeasureText(label,Font).Width+8;int left=Math.Max(2,Math.Min(Width-width-2,(int)x(time)-width/2));DrawText(g,label,new Rectangle(left,PlotBounds.Bottom+4,width,line),Style.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}
 using(var pen=new Pen(Style.Muted)){pen.DashStyle=DashStyle.Dot;g.DrawLine(pen,PlotBounds.Left,y(30),PlotBounds.Right,y(30));}using(var pen=new Pen(Style.Theme=="Night"?Style.Text:Color.FromArgb(233,100,83),2.3f))g.DrawLines(pen,Samples.Select(Project).ToArray());var peak=Project(new AltitudePoint{Utc=pick.Best,Alt=pick.Alt});using(var brush=new SolidBrush(Style.Text))g.FillEllipse(brush,peak.X-3,peak.Y-3,6,6);DrawText(g,"Shaded: dark sky · dotted: 30° limit",new Rectangle(2,Height-line-1,Width-4,line),Style.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
}
}
